package clientdata

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"testing"
)

const chengduGatherNpcOriginalBase64 = ""

func TestLoadNPCCreatorOriginalChengduGatherNpcEncodingFixture(t *testing.T) {
	raw, err := base64.StdEncoding.DecodeString(chengduGatherNpcOriginalBase64)
	if err != nil {
		t.Fatal(err)
	}
	if got := fmt.Sprintf("%x", sha256.Sum256(raw)); got != "2cab4fdcef65c5ee179c43f8e0ea5258c94237b0f500e5c22a37c82b04ee50a9" {
		t.Fatalf("fixture sha256=%s", got)
	}
	catalog, err := LoadNPCCreator(bytes.NewReader(raw), "city05_chengdu/GatherNpc.xml")
	if err != nil {
		t.Fatalf("LoadNPCCreator original GatherNpc.xml: %v", err)
	}
	if got := len(catalog.Instances); got != 5 {
		t.Fatalf("instances=%d, want 5", got)
	}
	if got := catalog.Instances[0].Attributes["desc"].Raw; got != "老人1" {
		t.Fatalf("decoded desc=%q, want 老人1", got)
	}
}
